 Model physicalA,physicalB;physicalA.Initialize(Wing(),800);physicalB.Initialize(Wing(),800);const float shortLeverWork=.5f*(800*1.f)*(20-2),longLeverWork=.5f*(800*2.f)*(10-1);auto workA=physicalA.ContactEnergy({2.58f,.43f,1.04f},{0,-1,0},shortLeverWork,1000,.02f),workB=physicalB.ContactEnergy({2.58f,.43f,1.04f},{0,-1,0},longLeverWork,1000,.02f);const auto tipA=physicalA.Deform({5,0,1},1),tipB=physicalB.Deform({5,0,1},1);Check(workA.valid&&workB.valid&&workA.deposited==shortLeverWork&&workB.deposited==longLeverWork&&std::fabs(tipA.y-tipB.y)<1e-6f&&std::fabs(tipA.y)>.1f,"equal accepted physical work produces equal bend despite different body deltaV and point speed");physicalA.ContactEnergy({3.5f,.1f,1.04f},{0,-1,0},shortLeverWork,1020,.02f);Check(std::fabs(physicalA.Deform({5,0,1},1).y-tipA.y)<1e-6f,"physical contact work is not charged again for another manifold point");const auto physicalRevision=physicalA.Revision();Check(!physicalA.ContactEnergy({2.58f,.43f,1.04f},{0,-1,0},nan,2000,.02f).valid&&!physicalA.ContactEnergy({2.58f,.43f,1.04f},{0,-1,0},-1,2000,.02f).valid&&physicalA.Revision()==physicalRevision,"invalid explicit work leaves material unchanged");
